head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf76100";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — page

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_attrReals();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf76100.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "div_91", attr: "__html", fn: function () { return ([String(String((dma_pageContext.get("totalSize") ?? ""))), String(String((dma_pageContext.get("pageIndex") ?? ""))), String(dma_page.get("pageCount"))].some(function (v) { return String(v === null ? '' : v).trim() !== ''; }) ? ("총건수: <span>" + String(String((dma_pageContext.get("totalSize") ?? ""))) + "</span> 페이지: <span>" + String(String((dma_pageContext.get("pageIndex") ?? ""))) + "/" + String(dma_page.get("pageCount")) + "</span>") : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        const v = a.fn();
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_page", fn: function(){ return (!(String(((dma_pageContext.get("page") ?? "")) === null ? '' : ((dma_pageContext.get("page") ?? ""))).length === 0)); } }, { id: "if_pageCount", fn: function(){ return (!(String(((dma_pageContext.get("page") ?? "")) === null ? '' : ((dma_pageContext.get("page") ?? ""))).length === 0) && (dma_page.get("pageCount") ?? (() => { throw new Error("unresolved:" + "page.pageCount"); })())!==0); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(filedownload vs sprtroom) — 어느 쪽인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name input_35_onclick
 * @description 「조회」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.input_35_onclick = async function(e){
    try {
        await scwin.search(1)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf76100.input_35_onclick' }); }
};

/**
 * @method
 * @name btn_reg_onclick
 * @description 「등록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_reg_onclick = function(e){
    try {
        scwin.reg()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf76100.btn_reg_onclick' }); }
};

/**
 * @method
 * @name grd_noticeList_oncellclick
 * @description grd_noticeList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_noticeList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_noticeList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_noticeList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { scwin.fileDownload(r["sprtRoomNo"], r["attachSeq"], r["attachFileNm"]); return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_noticeList.oncellclick' });
    }
};

/**
 * @method
 * @name __on_enter_1_ipt_keyword
 * @description on enter 1 ipt keyword 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_1_ipt_keyword = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await scwin.search() }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf76100.__on_enter_1_ipt_keyword' }); }
};

/**
 * @method
 * @name __on_enter_2_ipt_chrginstid
 * @description on enter 2 ipt chrginstid 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_2_ipt_chrginstid = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await scwin.search() }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf76100.__on_enter_2_ipt_chrgInstId' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_94_onclick
 * @description krxpage_pagenavigator_94 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_94_onclick = async function (index) {
    try {
    const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf76100.krxpage_pagenavigator_94_onclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_noticeList_fillAct
 * @description grd notice List fill Act 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_noticeList_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_noticeList');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getRowCount(); i++) {
            const r = dl.getRowJSON(i);
            const v = '-';
            if (r) {  }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_noticeList.fillAct' });
    }
};

/**
 * @method
 * @name detail
 * @description detail 처리
 * @param {*} ipt_sprtRoomNo ipt_sprtRoomNo
 * @returns {void}
 * @hidden N
 */
scwin.detail = function (ipt_sprtRoomNo) {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CreateDialogFrame
    const url = "/ods/sprtroom.do?sprtRoomNo=" + ipt_sprtRoomNo + "&method=readNoticeDetail&SCREN_ID=JLDSTF76120.jsp&SCREN_PROCES_TP_CD=01";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.frame.CreateDialogFrame("", (function (__u) { let __s = String(__u === null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), "공지사항 수정", { width: 1200, height: 900 }, {});
};

/**
 * @method
 * @name reg
 * @description reg 처리
 * @returns {void}
 * @hidden N
 */
scwin.reg = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CreateDialogFrame
    const url = "/ods/sprtroom.do?&method=moveJsp&SCREN_ID=JLDSTF76110.jsp&SCREN_PROCES_TP_CD=01";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.frame.CreateDialogFrame("", (function (__u) { let __s = String(__u === null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), "공지사항 등록", { width: 1200, height: 900 }, {});
};

/**
 * @method
 * @name search
 * @description search 처리
 * @param {*} ipt_pageIndex ipt_pageIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function (ipt_pageIndex) {
    if (ipt_pageIndex) {
        $('#ipt_pageIndex', $('#searchForm')).val(ipt_pageIndex);
    }
    if ($('#ipt_startDate', $('#searchForm')).val() !== "" && !$c.date.isDate($('#ipt_startDate', $('#searchForm')).val())) {
        await $c.win.alert("시작일자 형식이 틀립니다.");
        return;
    }
    if ($('#ipt_endDate', $('#searchForm')).val() !== "" && !$c.date.isDate($('#ipt_endDate', $('#searchForm')).val())) {
        await $c.win.alert("종료일자 형식이 틀립니다.");
        return;
    }
    if ($('#ipt_startDate', $('#searchForm')).val() !== "" && $('#ipt_endDate', $('#searchForm')).val() !== "" && $('#ipt_startDate', $('#searchForm')).val() > $('#ipt_endDate', $('#searchForm')).val()) {
        await $c.win.alert("시작일자는 종료일자 이전 이여야 합니다.");
        return;
    }
    $('#ipt_SCREN_ID', $('#searchForm')).val("/jldstf76100/jldstf76100.xml");
    $('#ipt_method', $('#searchForm')).val("readNoticeList");
    $c.util.getComponent('ipt_ldMktTpCd').setValue($('#slc_selLdMktTpCd option:selected').val());
    $('#searchForm').submit();
};

/**
 * @method
 * @name fileDownload
 * @description file Download 처리
 * @param {*} sprt_room_no sprt_room_no
 * @param {*} attach_seq attach_seq
 * @param {*} attach_file_nm attach_file_nm
 * @returns {void}
 * @hidden N
 */
scwin.fileDownload = function (sprt_room_no, attach_seq, attach_file_nm) {
    $('#ipt_sprtRoomNo', $('#attachForm')).val(sprt_room_no);
    $('#ipt_attachSeq', $('#attachForm')).val(attach_seq);
    $('#ipt_attachFileNm', $('#attachForm')).val(attach_file_nm);
    $('#ipt_SCREN_ID', $('#attachForm')).val("/jldods25000/jldods25000.xml");
    $('#ipt_gubun', $('#attachForm')).val("ODS");
    $('#attachForm').submit();
};
